<script lang="ts">
 import DashboardContent from '$lib/components/DashboardContent.svelte'; import DataTable from '$lib/components/DataTable.svelte'; import { Button } from '$lib/components/ui/button/index.js'; import { Dialog,DialogContent,DialogHeader,DialogTitle,DialogFooter,DialogClose } from '$lib/components/ui/dialog/index.js'; import { Plus,Trash2 } from 'lucide-svelte'; import { enhance } from '$app/forms'; import type { PageData } from './$types'; import type { ActionResult } from '@sveltejs/kit'; import { dispatchToast } from '$lib/notifications';
 interface Student{id:string;first_name:string;middle_name:string|null;last_name:string;admission_no:string;student_no:string|null;date_of_birth:string|null;gender:string|null;admission_date:string|null;nationality:string|null;grade:string|null;status:string}
 interface ActionData extends Record<string,unknown>{message?:string;errors?:Record<string,string[]>}
 const{data}:{data:PageData}=$props();const students=$derived(data.students);const pagination=$derived(data.pagination);let formData=$state<Record<string,unknown>>({});let errors=$state<Record<string,string[]>>({});let msg=$state<{type:'success'|'error';text:string}|null>(null);let submitting=$state(false);let showCreate=$state(false);let editingStudent=$state<Student|null>(null);let deletingStudent=$state<Student|null>(null);
 function handleSubmit(){submitting=true;errors={};msg=null;return async({result,update}:{result:ActionResult<ActionData,ActionData>;update:(_opts?:{reset?:boolean})=>void})=>{try{if(result.type==='failure'&&result.data){if(result.data.errors)errors=result.data.errors;if(result.data.message)msg={type:'error',text:result.data.message};dispatchToast('Error',result.data.message??'Please fix the form.')}if(result.type==='success'){msg={type:'success',text:result.data?.message??'Saved'};dispatchToast('Saved',result.data?.message??'Saved');formData={};editingStudent=null;showCreate=false}update()}finally{submitting=false}}}
 function openCreate(){formData={status:'active'};editingStudent=null;showCreate=true}function openEdit(s:Student){editingStudent=s;formData={...s};showCreate=true}function openDelete(s:Student){deletingStudent=s}
</script>
<DashboardContent title="Students" subtitle="Student master register and Student 360° records">{#snippet headerActions()}<Button href="/admin/students/import" size="sm" variant="outline">Import</Button><Button href="/admin/enrollment" size="sm" variant="outline">Enrollment</Button><Button href="/admin/admissions" size="sm" variant="outline">Admissions</Button><Button href="/admin/graduation" size="sm" variant="outline">Graduation</Button><Button onclick={openCreate} size="sm"><Plus class="h-3.5 w-3.5"/> Add Student</Button>{/snippet}<DataTable data={students} columns={[{key:'admission_no',label:'Adm No',sortable:true,html:true,render:(s:Student)=>`<a href="/admin/students/${s.id}" class="font-medium text-primary hover:underline">${s.admission_no}</a>`},{key:'student_no',label:'Student No',sortable:true},{key:'first_name',label:'Name',render:(s:Student)=>`${s.first_name} ${s.last_name}`},{key:'grade',label:'Legacy Grade',sortable:true},{key:'status',label:'Status',sortable:true}]} emptyMessage="No students found" onEdit={openEdit} onDelete={openDelete} server={{total:pagination.total,page:pagination.page,pageSize:pagination.pageSize,search:pagination.search,sortKey:pagination.sortKey,sortDir:pagination.sortDir}}/></DashboardContent>
<Dialog open={showCreate} onOpenChange={(o:boolean)=>{if(!o){showCreate=false;editingStudent=null}}}><DialogContent class="sm:max-w-2xl p-0"><DialogHeader class="border-b border-border px-6 py-4"><DialogTitle>{editingStudent?'Edit Student':'Add Student'}</DialogTitle></DialogHeader><form method="POST" action={editingStudent?'?/update':'?/create'} class="grid grid-cols-2 gap-4 px-6 py-5" use:enhance={handleSubmit}>{#if editingStudent}<input type="hidden" name="id" value={editingStudent.id}/>{/if}<label class="field-label">First Name<input name="first_name" required value={formData.first_name} class="field"/></label><label class="field-label">Middle Name<input name="middle_name" value={formData.middle_name} class="field"/></label><label class="field-label">Last Name<input name="last_name" required value={formData.last_name} class="field"/></label><label class="field-label">Student No<input name="student_no" value={formData.student_no} class="field" placeholder="STU-2026-001"/></label><label class="field-label">Admission No<input name="admission_no" required value={formData.admission_no} class="field"/></label><label class="field-label">Date of Birth<input name="date_of_birth" type="date" value={formData.date_of_birth} class="field"/></label><label class="field-label">Gender<select name="gender" value={formData.gender} class="field"><option value="">Not specified</option><option>Female</option><option>Male</option><option>Other</option></select></label><label class="field-label">Admission Date<input name="admission_date" type="date" value={formData.admission_date} class="field"/></label><label class="field-label">Nationality<input name="nationality" value={formData.nationality} class="field"/></label><label class="field-label">Birth Certificate No<input name="birth_certificate_no" value={formData.birth_certificate_no} class="field"/></label><label class="field-label">Legacy Grade<input name="grade" value={formData.grade} class="field"/></label><label class="field-label">Record Status<select name="status" value={formData.status??'active'} class="field"><option value="active">Active</option><option value="inactive">Inactive</option></select></label><p class="col-span-2 text-[11px] text-muted-foreground">Current class and stream are derived from Enrollment. Legacy Grade remains only for compatibility with existing records.</p>{#if msg}<div class="col-span-2 rounded-lg bg-muted px-4 py-2 text-sm">{msg.text}</div>{/if}<DialogFooter class="col-span-2"><DialogClose><button type="button" class="rounded-lg border px-4 py-2 text-sm">Cancel</button></DialogClose><Button type="submit" disabled={submitting}>{editingStudent?'Update Student':'Create Student'}</Button></DialogFooter></form></DialogContent></Dialog>
<Dialog open={!!deletingStudent} onOpenChange={(o:boolean)=>{if(!o)deletingStudent=null}}><DialogContent class="sm:max-w-sm p-0"><div class="px-6 py-5 text-center"><div class="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-red-50 text-destructive"><Trash2 class="h-6 w-6"/></div><h3 class="font-semibold">Archive Student</h3><p class="mt-2 text-sm text-muted-foreground">Historical records are retained; the student is removed from the active register.</p></div><div class="flex justify-end gap-3 border-t px-6 py-4"><DialogClose><button type="button" class="rounded-lg border px-4 py-2 text-sm">Cancel</button></DialogClose><form method="POST" action="?/delete" use:enhance><input type="hidden" name="id" value={deletingStudent?.id??''}/><Button type="submit" variant="destructive">Archive</Button></form></div></DialogContent></Dialog>
<style>.field-label{font-size:.75rem;font-weight:600}.field{display:block;width:100%;margin-top:.3rem;border:1px solid hsl(var(--border));background:white;border-radius:.5rem;padding:.55rem .7rem;font-size:.875rem;outline:none}</style>
